begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values ('c3000000-0000-4000-8000-000000000001','c3@example.invalid','{"terms_version":"ca-launch-v1"}');
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$update public.profiles set display_name='Unchecked' where id=auth.uid()$$,'42501','policy_acknowledgement_required','missing acknowledgement blocks direct profile write');
select throws_ok($$insert into public.applications(job_id,seeker_id) values('bbbbbbbb-0000-0000-0000-000000000001',auth.uid())$$,'42501','policy_acknowledgement_required','direct application insert cannot skip account acknowledgement');
select throws_ok($$select public.acknowledge_policies('ca-launch-v1',false,'ca-launch-v1',true,public.current_policy_identity())$$,'42501',null,'unchecked terms rejected');
select throws_ok($$select public.acknowledge_policies('old',true,'ca-launch-v1',true,public.current_policy_identity())$$,'42501',null,'old version rejected');
select throws_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',false,public.current_policy_identity())$$,'42501',null,'notice requires separate confirmation');
select lives_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity())$$,'self explicit acknowledgement');
select ok((select terms_accepted_at >= now() and privacy_notice_acknowledged_at >= now() from public.profiles where id=auth.uid()),'database timestamps');
select throws_ok($$update public.profiles set terms_accepted_at='1900-01-01' where id=auth.uid()$$,'42501',null,'REST cannot forge time');
select throws_ok($$update public.profiles set terms_version='old' where id=auth.uid()$$,'42501',null,'REST cannot rewrite version');
select lives_ok($$update public.profiles set display_name='Acknowledged' where id=auth.uid()$$,'corresponding profile edit succeeds');
select ok((select terms_accepted_at = privacy_notice_acknowledged_at from public.profiles where id=auth.uid()),'unrelated edit preserves acceptance');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.profiles set terms_version='older-policy',terms_accepted_at='2020-01-01' where id='c3000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$update public.profiles set city='Old policy' where id=auth.uid()$$,'42501','policy_acknowledgement_required','existing old acceptance cannot bypass next write');
select lives_ok($$select * from public.list_seeker_applications()$$,'old acceptance does not ban history reads');
select lives_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity())$$,'old account explicitly acknowledges current terms');
select ok((select terms_accepted_at >= now() from public.profiles where id=auth.uid()),'new version receives fresh DB time');
-- Retained user AND owner-submitted job cross a synthetic draft -> reviewed
-- transition in this rolled-back transaction; no global browser pointer changes.
reset role;
select set_config('request.jwt.claims','{}',true);
update public.profiles set role='employer' where id='c3000000-0000-4000-8000-000000000001';
insert into public.companies(id,owner_id,name,city) values('c3000000-0000-4000-8000-000000000002','c3000000-0000-4000-8000-000000000001','Identity toy','Oakland');
insert into auth.users(id,email) values('c3000000-0000-4000-8000-000000000003','c3-admin@example.invalid');
update public.profiles set role='admin' where id='c3000000-0000-4000-8000-000000000003';
select set_config('c3.old_identity',public.current_policy_identity(),true);
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true)$$,'42501',null,'old RPC cannot claim unspecified publication');
select throws_ok($$select public.activate_policy_publication(public.current_policy_identity(),'reviewed:'||repeat('a',64))$$,'42501',null,'user cannot activate policies');
select lives_ok($$insert into public.jobs(id,company_id,title,category,job_type,city,state,pay_min,pay_max,pay_unit,schedule_days,schedule_time_range,language_requirement,description,moderation_status,posting_policy_version,posting_policy_identity)
values('c3000000-0000-4000-8000-000000000004','c3000000-0000-4000-8000-000000000002','Identity toy','other','part_time','Oakland','CA',20,25,'hour','Mon','9-5','english_required','Toy work','pending','ca-launch-v1',public.current_policy_identity())$$,'owner explicitly submits job against actual draft');
select set_config('c3.old_terms_time',(select terms_accepted_at::text from public.profiles where id=auth.uid()),true);
select set_config('c3.old_posting_time',(select posting_policy_acknowledged_at::text from public.jobs where id='c3000000-0000-4000-8000-000000000004'),true);
reset role;
select set_config('request.jwt.claims','{}',true);
select lives_ok($$select public.activate_policy_publication(current_setting('c3.old_identity'),'reviewed:'||repeat('a',64))$$,'operator activates synthetic reviewed identity with CAS');
select throws_ok($$select public.activate_policy_publication(current_setting('c3.old_identity'),'reviewed:'||repeat('b',64))$$,'40001',null,'stale activation fails');
select ok((select policy_identity=current_setting('c3.old_identity') and terms_accepted_at=current_setting('c3.old_terms_time')::timestamptz from public.profiles where id='c3000000-0000-4000-8000-000000000001'),'activation never backfills profile acceptance');
select ok((select posting_policy_identity=current_setting('c3.old_identity') and posting_policy_acknowledged_at=current_setting('c3.old_posting_time')::timestamptz from public.jobs where id='c3000000-0000-4000-8000-000000000004'),'activation never backfills owner posting acceptance');
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select * from public.list_seeker_applications()$$,'transition preserves application history reads');
select is((select count(*) from public.jobs where id='c3000000-0000-4000-8000-000000000004'),1::bigint,'retained owner job remains readable');
select throws_ok($$update public.profiles set city='Berkeley' where id=auth.uid()$$,'42501','policy_acknowledgement_required','draft acceptance blocks next direct write after final activation');
select throws_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,current_setting('c3.old_identity'))$$,'42501',null,'old cached form identity cannot acknowledge final');
select throws_ok($$update public.profiles set policy_identity=public.current_policy_identity() where id=auth.uid()$$,'42501',null,'REST cannot forge current identity');
select lives_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity())$$,'existing account explicitly acknowledges final identity');
select ok((select policy_identity=public.current_policy_identity() and terms_accepted_at>current_setting('c3.old_terms_time')::timestamptz and privacy_notice_acknowledged_at=terms_accepted_at from public.profiles where id=auth.uid()),'changed identity receives fresh database timestamps');
select set_config('c3.final_terms_time',(select terms_accepted_at::text from public.profiles where id=auth.uid()),true);
select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity());
select is((select terms_accepted_at::text from public.profiles where id=auth.uid()),current_setting('c3.final_terms_time'),'same identity repeat preserves timestamp');
reset role;
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity());
select throws_ok($$select * from public.transition_job('c3000000-0000-4000-8000-000000000004','approve',(select updated_at from public.jobs where id='c3000000-0000-4000-8000-000000000004'))$$,'42501','posting_policy_acknowledgement_required','admin cannot approve old owner posting acceptance');
select throws_ok($$update public.jobs set moderation_status='approved' where id='c3000000-0000-4000-8000-000000000004'$$,'42501','posting_policy_acknowledgement_required','direct admin REST cannot approve old posting identity');
reset role;
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select status from public.transition_job('c3000000-0000-4000-8000-000000000004','pause',(select updated_at from public.jobs where id='c3000000-0000-4000-8000-000000000004'))),'updated','old posting identity can pause without new consent');
select throws_ok($$select * from public.transition_job('c3000000-0000-4000-8000-000000000004','resubmit',(select updated_at from public.jobs where id='c3000000-0000-4000-8000-000000000004'))$$,'42501','posting_policy_acknowledgement_required','old posting identity cannot resubmit');
select is((select status from public.transition_job('c3000000-0000-4000-8000-000000000004','close',(select updated_at from public.jobs where id='c3000000-0000-4000-8000-000000000004'))),'updated','old posting identity can close');
select ok((select posting_policy_identity=current_setting('c3.old_identity') and posting_policy_acknowledged_at=current_setting('c3.old_posting_time')::timestamptz from public.jobs where id='c3000000-0000-4000-8000-000000000004'),'pause and close preserve prior owner evidence');
select throws_ok($$update public.jobs set title='Stale edit' where id='c3000000-0000-4000-8000-000000000004'$$,'42501','posting_policy_acknowledgement_required','old posting identity fails direct edit');
select lives_ok($$update public.jobs set posting_policy_identity=public.current_policy_identity(),title='Explicit revised submission' where id='c3000000-0000-4000-8000-000000000004'$$,'owner explicitly submits current posting identity');
select ok((select posting_policy_acknowledged_at>current_setting('c3.old_posting_time')::timestamptz and posting_policy_identity=public.current_policy_identity() from public.jobs where id='c3000000-0000-4000-8000-000000000004'),'job identity change refreshes database timestamp');
reset role;
select set_config('request.jwt.claims','{}',true);
select ok(exists(select 1 from public.audit_logs where action='policy.acknowledged' and entity_id='c3000000-0000-4000-8000-000000000001' and metadata->'previous'->>'identity'=current_setting('c3.old_identity') and metadata->'current'->>'identity'=public.current_policy_identity()),'prior user acknowledgement retained in audit evidence');
select ok(exists(select 1 from public.audit_logs where action='policy.acknowledged' and entity_id='c3000000-0000-4000-8000-000000000004' and metadata->'previous'->>'identity'=current_setting('c3.old_identity') and metadata->'current'->>'identity'=public.current_policy_identity()),'prior posting acknowledgement retained in audit evidence');
select lives_ok($$select public.activate_policy_publication(public.current_policy_identity(),'reviewed:'||repeat('b',64))$$,'reviewed prose revision changes identity without changing version');
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$update public.profiles set city='Berkeley' where id=auth.uid()$$,'42501','policy_acknowledgement_required','same version revised content again requires explicit acknowledgement');

reset role;
select set_config('request.jwt.claims','{}',true);
update public.profiles set account_status='suspended' where id='c3000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity())$$,'42501','account_suspended','acknowledgement cannot bypass C2 suspension');
reset role;
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,public.current_policy_identity());
select set_config('c3.missing_identity',public.current_policy_identity(),true);
reset role;
select set_config('request.jwt.claims','{}',true);
delete from public.policy_publication;
select set_config('request.jwt.claims','{"sub":"c3000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select is(public.current_policy_identity(),null::text,'missing registry pointer is not inferred from user acceptance');
select throws_ok($$update public.profiles set city='Missing pointer' where id=auth.uid()$$,'42501','policy_acknowledgement_required','missing pointer blocks an otherwise-current actor write');
select throws_ok($$select public.acknowledge_policies('ca-launch-v1',true,'ca-launch-v1',true,current_setting('c3.missing_identity'))$$,'42501',null,'missing pointer cannot accept a cached identity');
select is((select count(*) from public.jobs where id='c3000000-0000-4000-8000-000000000004'),1::bigint,'missing pointer does not delete or hide retained history');
select * from finish();
rollback;
